	'hero_btn' => 'Réserver un samedi découverte',
	'hero_eyebrow' => 'Formation de deux ans en plomberie et chauffage',
	'hero_h1' => 'Maisons chaudes|ça commence|à l\'établi.',
	'hero_lede' => 'Une année à l\'établi dans nos halls de Wrenfield, une année en placement dans une entreprise en activité. Pour les adultes de tout âge ; aucune expérience du métier n\'est exigée.',
	'hero_link' => 'Comment se découpe une journée ↓',
	'hero_rail' => 'RENTRÉE SEPTEMBRE 2027',
	'hero_strip' => 'PLOMBERIE ET CHAUFFAGE',
	'hr_bench_l' => 'Ateliers, du lundi au jeudi',
